#!/usr/bin/env node
"use strict";

/**
 * Structural guards for the two-piece version / idle-loader wiring.
 *
 * src/version.js is generated by tools/sync-version.js and must stay a plain
 * version constant; the optional idle hand-off is loaded from the page markup
 * instead, so a `version:sync` run can never drop it or reintroduce drift.
 */

const assert = require("assert");
const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..");
const versionJs = fs.readFileSync(path.join(ROOT, "src", "version.js"), "utf8");
const markup = fs.readFileSync(path.join(ROOT, "pdp11.html"), "utf8");

// (a) Generated file: pure version constant, no hand-written loader logic.
assert(
    versionJs.includes("window.YAPDP_VERSION"),
    "src/version.js must assign window.YAPDP_VERSION"
);
assert(
    !versionJs.includes('document.createElement("script")'),
    "src/version.js must not contain a hand-written script loader"
);
assert(
    !versionJs.includes("idle-manager"),
    "src/version.js must not reference the idle manager"
);

// (b) Markup: the classic version script tag stays synchronous (no defer/async/
// type="module"), and the idle loader sits right after it.
const versionTag = markup.match(/<script\s+src=['"]src\/version\.js['"][^>]*>/);
assert(versionTag, "pdp11.html must load src/version.js");
assert(
    !/\b(defer|async)\b/.test(versionTag[0]) && !/type\s*=/.test(versionTag[0]),
    "src/version.js must stay a plain synchronous classic script"
);

const versionAt = markup.indexOf(versionTag[0]);
const loaderAt = markup.indexOf("src/idle-manager.js");
assert(loaderAt > versionAt, "pdp11.html must load src/idle-manager.js");
assert(
    markup.includes('params.has("idle-timeout")') &&
        markup.includes('params.has("idle-redirect")'),
    "the inline loader must gate on idle-timeout / idle-redirect"
);
// A static tag would start its own line; the loader writes its tag inside a
// document.write() string, so match only line-initial markup.
assert(
    !/^[ \t]*<script\s+src=['"]src\/idle-manager\.js['"]/m.test(markup),
    "src/idle-manager.js must stay opt-in (no static script tag)"
);
assert(
    /document\.write\(["']<script src='src\/idle-manager\.js'><\\\/script>["']\)/.test(markup),
    "the inline loader must inject src/idle-manager.js via document.write"
);

console.log("version-loader: all checks passed");
